import React, { useState, useEffect, useMemo, memo, useCallback } from "react";
import { useI18n } from "../contexts/I18nContext";
import { useStatus } from "../contexts/StatusContext";
import { Client } from "../types/api";
import "../animations.css";
import {
  CpuIcon,
  CheckIcon,
  AlertIcon,
  ProcessingIcon,
  MemoryIcon,
  SpeedIcon,
  AnimatedHeartIcon,
  WarningIcon,
  ErrorIcon,
} from "./Icons";

interface WorkerMetricsData {
  timestamp: string;
  cpu_usage: number;
  memory_usage: number;
  active_tasks: number;
  completed_tasks: number;
  failed_tasks: number;
  response_time: number;
}

// Новий інтерфейс для системних ресурсів
interface SystemResourceData {
  cpu_usage: number;
  memory_usage: number;
  disk_usage: number;
  network_in: number;
  network_out: number;
  uptime: number;
}

interface WorkerMetricsProps {
  clients: Client[];
}

// Компонент системного моніторингу ресурсів
const SystemResourceMonitor: React.FC<{ 
  selectedClient?: Client | null;
  resourceData?: SystemResourceData;
}> = ({ selectedClient, resourceData }) => {
  const { t } = useI18n();
  const { state } = useStatus();

  const getUsageColor = (value: number) => {
    if (value > 80) return "bg-red-500";
    if (value > 60) return "bg-yellow-500";
    return "bg-green-500";
  };

  const getUsageTextColor = (value: number) => {
    if (value > 80) return "text-red-600";
    if (value > 60) return "text-yellow-600";
    return "text-green-600";
  };

  const formatBytes = (bytes: number) => {
    if (bytes === 0) return "0 B";
    const k = 1024;
    const sizes = ["B", "KB", "MB", "GB"];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + " " + sizes[i];
  };

  const formatUptime = (seconds: number) => {
    const hours = Math.floor(seconds / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    return `${hours}г ${minutes}хв`;
  };

  // Використовуємо дані обраного клієнта або загальні системні дані
  const systemData = resourceData || {
    cpu_usage: state.metrics?.system?.cpu_usage || Math.random() * 100,
    memory_usage: state.metrics?.system?.memory_usage || 40 + Math.random() * 40,
    disk_usage: state.metrics?.system?.disk_usage || 20 + Math.random() * 60,
    network_in: Math.random() * 1024 * 1024, // Демо дані мережевого трафіку
    network_out: Math.random() * 1024 * 1024, // Демо дані мережевого трафіку
    uptime: state.health?.uptime || 3600 + Math.random() * 86400, // Демо час роботи
  };

  const resources = [
    {
      name: "CPU",
      value: systemData.cpu_usage,
      icon: <CpuIcon size="md" className="text-blue-600" />,
      color: "blue",
    },
    {
      name: t("dashboard.memory"),
      value: systemData.memory_usage,
      icon: <MemoryIcon size="md" className="text-green-600" />,
      color: "green",
    },
    {
      name: t("dashboard.disk"),
      value: systemData.disk_usage,
      icon: "💿",
      color: "purple",
    },
  ];

  return (
    <div className="bg-white rounded-xl shadow-sm border border-secondary-100 p-6">
      <h3 className="text-lg font-semibold text-secondary-900 mb-6 flex items-center">
        📊 {t("dashboard.resourceMonitor")}
        {selectedClient && (
          <span className="ml-2 text-sm text-secondary-600 font-normal">
            - {selectedClient.client_name || selectedClient.client_id}
          </span>
        )}
      </h3>

      <div className="space-y-6">
        {resources.map((resource, index) => (
          <div
            key={resource.name}
            className="space-y-3 p-4 bg-secondary-50 rounded-lg hover:bg-secondary-100 transition-colors duration-200"
          >
            <div className="flex items-center justify-between">
              <div className="flex items-center space-x-3">
                {typeof resource.icon === 'string' ? (
                  <span className="text-2xl">{resource.icon}</span>
                ) : (
                  resource.icon
                )}
                <span className="text-base font-medium text-secondary-800">
                  {resource.name}
                </span>
              </div>
              <span className={`text-lg font-bold ${getUsageTextColor(resource.value)}`}>
                {Math.round(resource.value)}%
              </span>
            </div>
            <div className="w-full bg-secondary-200 rounded-full h-3">
              <div
                className={`h-3 rounded-full transition-all duration-500 ${getUsageColor(resource.value)}`}
                style={{ width: `${Math.min(resource.value, 100)}%` }}
              />
            </div>
          </div>
        ))}

        {/* Мережева активність */}
        <div className="grid grid-cols-2 gap-4 mt-6">
          <div className="text-center p-4 bg-blue-50 rounded-lg">
            <p className="text-lg font-bold text-blue-600">
              {formatBytes(systemData.network_in)}
            </p>
            <p className="text-sm text-blue-700">{t("dashboard.incomingTraffic")}</p>
          </div>
          <div className="text-center p-4 bg-green-50 rounded-lg">
            <p className="text-lg font-bold text-green-600">
              {formatBytes(systemData.network_out)}
            </p>
            <p className="text-sm text-green-700">{t("dashboard.outgoingTraffic")}</p>
          </div>
        </div>

        {/* Час роботи */}
        {systemData.uptime > 0 && (
          <div className="pt-4 border-t border-secondary-200">
            <div className="flex justify-between items-center">
              <span className="text-sm text-secondary-600">{t("dashboard.systemUptime")}</span>
              <span className="text-lg font-bold text-purple-600">
                {formatUptime(systemData.uptime)}
              </span>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

const MetricChart: React.FC<{
  title: string;
  data: WorkerMetricsData[];
  dataKey: keyof WorkerMetricsData;
  color: string;
  unit?: string;
}> = memo(
  ({ title, data, dataKey, color, unit = "" }) => {
    const { maxValue, range, points } = useMemo(() => {
      // Handle empty or invalid data
      if (!data || data.length === 0) {
        return { maxValue: 0, range: 1, points: [] };
      }

      const values = data.map((d) => {
        const val = Number(d[dataKey]);
        return isNaN(val) ? 0 : val;
      }).filter(val => !isNaN(val));

      if (values.length === 0) {
        return { maxValue: 0, range: 1, points: [] };
      }

      const max = Math.max(...values);
      const min = Math.min(...values);
      const r = max - min || 1;

      const chartPoints = data.map((point, index) => {
        const x = 40 + (index * 340) / Math.max(data.length - 1, 1);
        const value = Number(point[dataKey]);
        const safeValue = isNaN(value) ? 0 : value;
        const y = 160 - ((safeValue - min) / r) * 120;
        return { 
          x, 
          y: isNaN(y) ? 160 : y, 
          value: safeValue, 
          timestamp: point.timestamp 
        };
      });

      return { maxValue: max, range: r, points: chartPoints };
    }, [data, dataKey]);

    return (
      <div className="bg-white rounded-xl shadow-sm p-6 transform hover:scale-105 transition-all duration-300 hover:shadow-lg">
        <h3 className="text-lg font-semibold text-secondary-900 mb-4">
          {title}
        </h3>
        <div className="relative h-48">
          {points.length === 0 ? (
            <div className="flex items-center justify-center h-full">
              <p className="text-secondary-500 text-sm">Немає даних для відображення</p>
            </div>
          ) : (
            <svg className="w-full h-full" viewBox="0 0 400 160">
            {/* Grid lines */}
            {[0, 1, 2, 3, 4].map((i) => (
              <line
                key={i}
                x1="40"
                y1={40 + i * 30}
                x2="380"
                y2={40 + i * 30}
                stroke="#f3f4f6"
                strokeWidth="1"
              />
            ))}

            {/* Y-axis labels */}
            {[0, 1, 2, 3, 4].map((i) => {
              const value = maxValue - (i * range) / 4;
              const displayValue = isNaN(value) ? 0 : value;
              return (
                <text
                  key={i}
                  x="35"
                  y={45 + i * 30}
                  textAnchor="end"
                  className="text-xs fill-secondary-500"
                >
                  {displayValue.toFixed(1)}
                  {unit}
                </text>
              );
            })}

            {/* Chart line */}
            {points.length > 1 && (
              <polyline
                fill="none"
                stroke={color}
                strokeWidth="2"
                points={points.map((p) => `${p.x},${p.y}`).join(" ")}

                style={{
                  strokeDasharray: "1000",
                  strokeDashoffset: "1000",
                  animation: "drawLine 2s ease-out forwards",
                }}
              />
            )}

            {/* Data points */}
            {points.map((point, index) => (
              <circle
                key={index}
                cx={point.x}
                cy={point.y}
                r="3"
                fill={color}
                className="hover:r-4 transition-all cursor-pointer"

              >
                <title>{`${title}: ${point.value}${unit} at ${point.timestamp}`}</title>
              </circle>
            ))}
          </svg>
          )}
        </div>
      </div>
    );
  },
  (prevProps, nextProps) => {
    // Custom comparison for MetricChart
    return (
      prevProps.title === nextProps.title &&
      prevProps.dataKey === nextProps.dataKey &&
      prevProps.color === nextProps.color &&
      prevProps.unit === nextProps.unit &&
      prevProps.data.length === nextProps.data.length &&
      prevProps.data.every(
        (item, index) =>
          item[prevProps.dataKey] ===
          nextProps.data[index]?.[nextProps.dataKey],
      )
    );
  },
);

const WorkerCard: React.FC<{
  client: Client;
  metrics: WorkerMetricsData[];
}> = memo(
  ({ client, metrics }) => {
    const isHealthy = client.is_healthy !== false;
    const currentLoad = client.current_load || 0;
    const maxTasks = client.max_concurrent_tasks || 1;
    const loadPercentage = Math.min((currentLoad / maxTasks) * 100, 100);

    const getStatusColor = (status: string) => {
      switch (status) {
        case "idle":
          return "bg-success-100 text-success-800";
        case "busy":
          return "bg-warning-100 text-warning-800";
        case "overloaded":
          return "bg-error-100 text-error-800";
        case "maintenance":
          return "bg-secondary-100 text-secondary-800";
        case "error":
          return "bg-error-100 text-error-800";
        default:
          return "bg-secondary-100 text-secondary-800";
      }
    };

    const getLoadColor = () => {
      if (loadPercentage < 50) return "bg-success-500";
      if (loadPercentage < 80) return "bg-warning-500";
      return "bg-error-500";
    };

    return (
      <div className="bg-white rounded-xl shadow-sm p-6 space-y-4 card-hover hover-glow">
        {/* Header */}
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-3">
            <div className="p-2 bg-primary-50 rounded-lg">
              {client.client_type === "worker_api" ? (
                <CpuIcon
                  size="lg"
                  className="text-primary-600"
                />
              ) : (
                <MemoryIcon
                  size="lg"
                  className="text-primary-600"
                />
              )}
            </div>
            <div>
              <h3 className="text-lg font-semibold text-secondary-900">
                {client.client_name || client.client_id}
              </h3>
              <p className="text-sm text-secondary-600">
                {client.client_type === "worker_api" ? "API Worker" : "Worker"}
              </p>
            </div>
          </div>
          <div className="flex items-center space-x-3">
            <span
              className={`inline-flex items-center px-3 py-1 rounded-full text-xs font-medium transition-all duration-300 ${getStatusColor(client.worker_status || "unknown")}`}
            >
              {client.worker_status || "Unknown"}
            </span>
            <div className="flex items-center">
              {isHealthy ? (
                <AnimatedHeartIcon size="md" className="text-success-500" />
              ) : (
                <ErrorIcon
                  size="md"
                  className="text-error-500"
                />
              )}
            </div>
          </div>
        </div>

        {/* Load indicator */}
        <div>
          <div className="flex justify-between text-sm text-secondary-600 mb-1">
            <span>Навантаження</span>
            <span>
              {currentLoad}/{maxTasks} задач
            </span>
          </div>
          <div className="w-full bg-secondary-200 rounded-full h-2 overflow-hidden">
            <div
              className={`h-2 rounded-full transition-all duration-700 ease-out ${getLoadColor()}`}
              style={{ width: `${loadPercentage}%` }}
            />
          </div>
        </div>

        {/* Stats */}
        <div className="grid grid-cols-2 gap-4">
          <div className="bg-secondary-50 rounded-lg p-4 text-center card-hover hover-icon-scale">
            <div className="flex items-center justify-center mb-2">
              <ProcessingIcon size="md" className="text-secondary-600 mr-2" />
            </div>
            <p className="text-2xl font-bold text-secondary-900">
              {client.stats?.total_tasks || 0}
            </p>
            <p className="text-sm text-secondary-600">Всього задач</p>
          </div>
          <div className="bg-success-50 rounded-lg p-4 text-center card-hover hover-icon-scale">
            <div className="flex items-center justify-center mb-2">
              <CheckIcon size="md" className="text-success-600 mr-2" />
            </div>
            <p className="text-2xl font-bold text-success-600">
              {client.stats?.successful_tasks || 0}
            </p>
            <p className="text-sm text-secondary-600">Успішно</p>
          </div>
          <div className="bg-error-50 rounded-lg p-4 text-center card-hover hover-icon-scale">
            <div className="flex items-center justify-center mb-2">
              <AlertIcon size="md" className="text-error-600 mr-2" />
            </div>
            <p className="text-2xl font-bold text-error-600">
              {client.stats?.failed_tasks || 0}
            </p>
            <p className="text-sm text-secondary-600">Помилки</p>
          </div>
          <div className="bg-primary-50 rounded-lg p-4 text-center card-hover hover-icon-scale">
            <div className="flex items-center justify-center mb-2">
              <SpeedIcon size="md" className="text-primary-600 mr-2" />
            </div>
            <p className="text-2xl font-bold text-primary-600">
              {client.stats?.average_processing_time
                ? `${client.stats.average_processing_time.toFixed(2)}s`
                : "N/A"}
            </p>
            <p className="text-sm text-secondary-600">Сер. час</p>
          </div>
        </div>

        {/* Mini charts */}
        {useMemo(() => {
          if (metrics.length === 0) return null;

          const recentMetrics = metrics.slice(-10);
          const maxActiveTasks = Math.max(
            ...metrics.map((m) => m.active_tasks),
            1,
          );
          const maxResponseTime = Math.max(
            ...metrics.map((m) => m.response_time),
            1,
          );

          const activeTasksPoints = recentMetrics
            .map((point, index) => {
              const x = (index * 180) / Math.max(recentMetrics.length - 1, 1);
              const y = 50 - (point.active_tasks * 40) / maxActiveTasks;
              return `${x + 10},${y + 5}`;
            })
            .join(" ");

          const responseTimePoints = recentMetrics
            .map((point, index) => {
              const x = (index * 180) / Math.max(recentMetrics.length - 1, 1);
              const y = 50 - (point.response_time * 40) / maxResponseTime;
              return `${x + 10},${y + 5}`;
            })
            .join(" ");

          return (
            <div
              className="grid grid-cols-2 gap-4"
              key={`mini-charts-${client.client_id}`}
            >
              <div>
                <p className="text-sm font-medium text-secondary-700 mb-2">
                  Активні задачі
                </p>
                <div className="h-16 relative">
                  <svg className="w-full h-full" viewBox="0 0 200 60">
                    <polyline
                      fill="none"
                      stroke="#3b82f6"
                      strokeWidth="2"
                      points={activeTasksPoints}
                      className="mini-chart-line"
                    />
                  </svg>
                </div>
              </div>
              <div>
                <p className="text-sm font-medium text-secondary-700 mb-2">
                  Час відповіді
                </p>
                <div className="h-16 relative">
                  <svg className="w-full h-full" viewBox="0 0 200 60">
                    <polyline
                      fill="none"
                      stroke="#10b981"
                      strokeWidth="2"
                      points={responseTimePoints}
                      className="mini-chart-line"
                      style={{ animationDelay: "0.5s" }}
                    />
                  </svg>
                </div>
              </div>
            </div>
          );
        }, [metrics, client.client_id])}
      </div>
    );
  },
  (prevProps, nextProps) => {
    // Custom comparison for better performance
    return (
      prevProps.client.client_id === nextProps.client.client_id &&
      prevProps.client.connection_status ===
        nextProps.client.connection_status &&
      prevProps.client.worker_status === nextProps.client.worker_status &&
      prevProps.client.active_tasks_count ===
        nextProps.client.active_tasks_count &&
      prevProps.metrics.length === nextProps.metrics.length &&
      JSON.stringify(prevProps.client.stats) ===
        JSON.stringify(nextProps.client.stats)
    );
  },
);

const WorkerMetrics: React.FC<WorkerMetricsProps> = ({ clients }) => {
  const { t } = useI18n();
  const [selectedWorker, setSelectedWorker] = useState<string | null>(null);
  const [metricsData, setMetricsData] = useState<
    Record<string, WorkerMetricsData[]>
  >({});
  const [timeRange, setTimeRange] = useState<"1h" | "6h" | "24h" | "7d">("1h");

  // Memoize filtered workers to prevent unnecessary re-renders
  const workers = useMemo(
    () =>
      clients.filter(
        (client) =>
          client.client_type === "worker" ||
          client.client_type === "worker_api",
      ),
    [clients],
  );

  // Розширюємо для всіх типів клієнтів (воркери, API-воркери, боти, стрім-хаби)
  const allClients = useMemo(
    () => clients,
    [clients],
  );

  const { apiWorkers, regularWorkers, bots, streamHubs } = useMemo(
    () => ({
      apiWorkers: workers.filter(
        (worker) => worker.client_type === "worker_api",
      ),
      regularWorkers: workers.filter(
        (worker) => worker.client_type === "worker",
      ),
      bots: clients.filter(
        (client) => client.client_type === "bot",
      ),
      streamHubs: clients.filter(
        (client) => client.client_type === "stream_hub",
      ),
    }),
    [workers, clients],
  );

  // Memoize worker selection handler
  const handleWorkerSelect = useCallback((workerId: string) => {
    setSelectedWorker((prev) => (prev === workerId ? null : workerId));
  }, []);

  // Memoize time range change handler
  const handleTimeRangeChange = useCallback(
    (e: React.ChangeEvent<HTMLSelectElement>) => {
      setTimeRange(e.target.value as any);
    },
    [],
  );

  // Real metrics data from clients with fallback demo data
  const stableMetricsData = useMemo(() => {
    const newMetricsData: Record<string, WorkerMetricsData[]> = {};
    allClients.forEach((client) => {
      // Generate demo data for visualization (will be replaced with real API data)
      const demoData: WorkerMetricsData[] = [];
      const now = new Date();

      for (let i = 0; i < 20; i++) {
        const timestamp = new Date(now.getTime() - (19 - i) * 5 * 60 * 1000);
        demoData.push({
          timestamp: timestamp.toISOString(),
          cpu_usage: Math.random() * 100,
          memory_usage: 40 + Math.random() * 40,
          active_tasks: Math.floor(Math.random() * 10),
          completed_tasks: Math.floor(Math.random() * 100),
          failed_tasks: Math.floor(Math.random() * 5),
          response_time: 0.1 + Math.random() * 2,
        });
      }

      newMetricsData[client.client_id] = demoData;
    });
    return newMetricsData;
  }, [allClients, timeRange]);

  // Update metrics data only when stable data changes with optimized rendering
  useEffect(() => {
    let rafId: number;
    const timer = setTimeout(() => {
      rafId = requestAnimationFrame(() => {
        setMetricsData(stableMetricsData);
      });
    }, 100); // Small delay to debounce rapid changes

    return () => {
      clearTimeout(timer);
      if (rafId) {
        cancelAnimationFrame(rafId);
      }
    };
  }, [stableMetricsData]);

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-secondary-900">
            {t("metrics.title")}
          </h1>
          <p className="text-secondary-600">
            {t("metrics.subtitle")}
          </p>
        </div>
        <div className="flex items-center space-x-4">
          <select
            value={timeRange}
            onChange={handleTimeRangeChange}
            className="px-3 py-2 border border-secondary-300 rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-primary-500 transition-all duration-300 hover:shadow-md hover:border-primary-300"
          >
            <option value="1h">{t("metrics.lastHour")}</option>
            <option value="6h">{t("metrics.last6Hours")}</option>
            <option value="24h">{t("metrics.last24Hours")}</option>
            <option value="7d">{t("metrics.lastWeek")}</option>
          </select>
        </div>
      </div>

      {/* Summary stats */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <div className="bg-white rounded-xl shadow-sm p-6 card-hover">
          <div className="flex items-center">
            <div className="p-3 rounded-lg bg-primary-100 text-primary-600">
              <CpuIcon size="lg" />
            </div>
            <div className="ml-4">
              <p className="text-sm font-medium text-secondary-600">
                {t("metrics.totalWorkers")}
              </p>
              <p className="text-2xl font-bold text-secondary-900">
                {workers.length}
              </p>
            </div>
          </div>
        </div>

        <div className="bg-white rounded-xl shadow-sm p-6 card-hover">
          <div className="flex items-center">
            <div className="p-3 rounded-lg bg-success-100 text-success-600">
              <CheckIcon size="lg" />
            </div>
            <div className="ml-4">
              <p className="text-sm font-medium text-secondary-600">{t("common.active")}</p>
              <p className="text-2xl font-bold text-secondary-900">
                {
                  workers.filter((w) => w.connection_status === "connected")
                    .length
                }
              </p>
            </div>
          </div>
        </div>

        <div className="bg-white rounded-xl shadow-sm p-6 card-hover">
          <div className="flex items-center">
            <div className="p-3 rounded-lg bg-warning-100 text-warning-600">
              <AlertIcon size="lg" />
            </div>
            <div className="ml-4">
              <p className="text-sm font-medium text-secondary-600">
                {t("clients.workerApi")}
              </p>
              <p className="text-2xl font-bold text-secondary-900">
                {apiWorkers.length}
              </p>
            </div>
          </div>
        </div>

        <div className="bg-white rounded-xl shadow-sm p-6 card-hover">
          <div className="flex items-center">
            <div className="p-3 rounded-lg bg-secondary-100 text-secondary-600">
              <ProcessingIcon size="lg" />
            </div>
            <div className="ml-4">
              <p className="text-sm font-medium text-secondary-600">
                {t("metrics.activeTasks")}
              </p>
              <p className="text-2xl font-bold text-secondary-900">
                {workers.reduce(
                  (sum, w) => sum + (w.active_tasks_count || 0),
                  0,
                )}
              </p>
            </div>
          </div>
        </div>
      </div>

      {/* Worker cards */}
      <div>
              <h2 className="text-xl font-semibold text-secondary-900 mb-4">
        {t("clients.standardWorkers")}
      </h2>
        {regularWorkers.length > 0 ? (
          <div className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-6">
            {regularWorkers.map((worker) => (
              <div key={`regular-${worker.client_id}`}>
                <WorkerCard
                  client={worker}
                  metrics={metricsData[worker.client_id] || []}
                />
              </div>
            ))}
          </div>
        ) : (
          <div className="bg-white rounded-xl shadow-sm p-8 text-center">
            <p className="text-secondary-500">
              {t("metrics.noStandardWorkers")}
            </p>
          </div>
        )}
      </div>

      {/* API Worker cards */}
      <div>
        <h2 className="text-xl font-semibold text-secondary-900 mb-4">
          {t("clients.apiWorkers")}
        </h2>
        {apiWorkers.length > 0 ? (
          <div className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-6">
            {apiWorkers.map((worker) => (
              <div key={`api-${worker.client_id}`}>
                <WorkerCard
                  client={worker}
                  metrics={metricsData[worker.client_id] || []}
                />
              </div>
            ))}
          </div>
        ) : (
          <div className="bg-white rounded-xl shadow-sm p-8 text-center">
                          <p className="text-secondary-500">{t("metrics.noApiWorkers")}</p>
          </div>
        )}
      </div>

      {/* Detailed charts for selected client */}
      {selectedWorker && metricsData[selectedWorker] && (
        <div>
          <h2 className="text-xl font-semibold text-secondary-900 mb-4">
            Детальні метрики:{" "}
            {allClients.find((c) => c.client_id === selectedWorker)?.client_name ||
              selectedWorker}
          </h2>
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            <MetricChart
              key={`cpu-${selectedWorker}-${timeRange}`}
              title="Використання CPU"
              data={metricsData[selectedWorker]}
              dataKey="cpu_usage"
              color="#3b82f6"
              unit="%"
            />
            <MetricChart
              key={`memory-${selectedWorker}-${timeRange}`}
              title="Використання пам'яті"
              data={metricsData[selectedWorker]}
              dataKey="memory_usage"
              color="#10b981"
              unit="%"
            />
            <MetricChart
              key={`tasks-${selectedWorker}-${timeRange}`}
              title="Активні задачі"
              data={metricsData[selectedWorker]}
              dataKey="active_tasks"
              color="#f59e0b"
            />
            <MetricChart
              key={`response-${selectedWorker}-${timeRange}`}
              title="Час відповіді"
              data={metricsData[selectedWorker]}
              dataKey="response_time"
              color="#ef4444"
              unit="s"
            />
          </div>
        </div>
      )}

      {/* Bots section */}
      {bots.length > 0 && (
        <div>
          <h2 className="text-xl font-semibold text-secondary-900 mb-4">
            🤖 Боти
          </h2>
          <div className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-6">
            {bots.map((bot) => (
              <div key={`bot-${bot.client_id}`}>
                <WorkerCard
                  client={bot}
                  metrics={metricsData[bot.client_id] || []}
                />
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Stream Hubs section */}
      {streamHubs.length > 0 && (
        <div>
          <h2 className="text-xl font-semibold text-secondary-900 mb-4">
            🌊 Стрім-хаби
          </h2>
          <div className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-6">
            {streamHubs.map((hub) => (
              <div key={`hub-${hub.client_id}`}>
                <WorkerCard
                  client={hub}
                  metrics={metricsData[hub.client_id] || []}
                />
              </div>
            ))}
          </div>
        </div>
      )}

      {/* System Resource Monitor */}
      {selectedWorker && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <SystemResourceMonitor
            selectedClient={allClients.find(c => c.client_id === selectedWorker)}
          />
          {/* Placeholder for additional system info */}
          <div className="bg-white rounded-xl shadow-sm border border-secondary-100 p-6">
            <h3 className="text-lg font-semibold text-secondary-900 mb-4">
              📈 Додаткова інформація
            </h3>
            <div className="space-y-4">
              <div className="text-sm text-secondary-600">
                <p>Тип клієнта: <span className="font-medium text-secondary-900">
                  {allClients.find(c => c.client_id === selectedWorker)?.client_type}
                </span></p>
                <p>Статус з'єднання: <span className="font-medium text-secondary-900">
                  {allClients.find(c => c.client_id === selectedWorker)?.connection_status}
                </span></p>
                <p>Активні завдання: <span className="font-medium text-secondary-900">
                  {allClients.find(c => c.client_id === selectedWorker)?.active_tasks_count || 0}
                </span></p>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Client selection */}
      {allClients.length > 0 && (
        <div className="bg-white rounded-xl shadow-sm p-6">
          <h3 className="text-lg font-semibold text-secondary-900 mb-4">
            Вибрати клієнт для детального аналізу системних ресурсів
          </h3>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {allClients.map((client) => (
              <button
                key={`select-${client.client_id}`}
                onClick={() => handleWorkerSelect(client.client_id)}
                className={`p-4 rounded-lg border-2 transition-all duration-200 text-left card-hover ${
                  selectedWorker === client.client_id
                    ? "border-primary-500 bg-primary-50"
                    : "border-secondary-200 hover:border-secondary-300"
                }`}
              >
                <div className="flex items-center justify-between">
                  <div>
                    <p className="font-medium text-secondary-900">
                      {client.client_name || client.client_id}
                    </p>
                    <p className="text-sm text-secondary-600">
                      {client.client_type === "worker_api"
                        ? "API Worker"
                        : client.client_type === "worker"
                        ? "Worker"
                        : client.client_type === "bot"
                        ? "Bot"
                        : client.client_type === "stream_hub"
                        ? "Stream Hub"
                        : client.client_type}
                    </p>
                  </div>
                  <div
                    className={`w-3 h-3 rounded-full ${
                      client.connection_status === "connected"
                        ? "bg-success-500"
                        : "bg-error-500"
                    }`}
                  />
                </div>
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export { WorkerMetrics };
